  state,
  runtime,
  terminalPresented,
  railCompact,
  onRailCompact,
  onRollup,
  onOpenPath,
  onOpenWebLink,
  preferences,
  onOpenSettings,
  onOpenTerminalSettings,
  onOpenHarnessSettings,
  onAddHarness,
}: TerminalWorkspaceCollectionProps): ReactElement {
